using System;
using System.IO;

namespace UI_Desktop.Store;

internal static class StoreSteamConnectionHeaderHtml
{
	private static class Icons
	{
		internal static readonly string Steam = Read("steam");

		internal static readonly string Chevron = Read("chevron-down");

		internal static readonly string Close = Read("x-lg");

		internal static readonly string Check = Read("check-lg");

		internal static readonly string Dash = Read("dash-lg");

		internal static readonly string Error = Read("exclamation-lg");

		internal static readonly string Open = Read("box-arrow-up-right");

		internal static readonly string Refresh = Read("arrow-clockwise");

		private static string Read(string name)
		{
			using Stream? stream = typeof(StoreSteamConnectionHeaderHtml).Assembly.GetManifestResourceStream("NestG.SteamConnection.Icons." + name + ".svg");
			if (stream == null)
			{
				return string.Empty;
			}
			using MemoryStream memoryStream = new MemoryStream();
			stream.CopyTo(memoryStream);
			return "data:image/svg+xml;base64," + Convert.ToBase64String(memoryStream.ToArray());
		}
	}

	internal static string Styles => $".nestg-steam-control, .nestg-steam-panel {{\n    --nestg-steam-icon-steam:url(\"{Icons.Steam}\"); --nestg-steam-icon-chevron:url(\"{Icons.Chevron}\");\n    --nestg-steam-icon-close:url(\"{Icons.Close}\"); --nestg-steam-icon-check:url(\"{Icons.Check}\");\n    --nestg-steam-icon-dash:url(\"{Icons.Dash}\"); --nestg-steam-icon-error:url(\"{Icons.Error}\");\n    --nestg-steam-icon-open:url(\"{Icons.Open}\"); --nestg-steam-icon-refresh:url(\"{Icons.Refresh}\");\n}}\n.nestg-steam-glyph {{ display:block; flex:0 0 auto; width:20px; height:20px; background:currentColor; mask:var(--nestg-steam-glyph-image) center/contain no-repeat; }}\n.nestg-steam-glyph-steam {{ --nestg-steam-glyph-image:var(--nestg-steam-icon-steam); }}\n.nestg-steam-glyph-status {{ --nestg-steam-glyph-image:var(--nestg-steam-icon-dash); }}\n.nestg-steam-panel [data-glyph=\"check\"] .nestg-steam-glyph-status {{ --nestg-steam-glyph-image:var(--nestg-steam-icon-check); }}\n.nestg-steam-panel [data-glyph=\"error\"] .nestg-steam-glyph-status {{ --nestg-steam-glyph-image:var(--nestg-steam-icon-error); }}\n.nestg-steam-panel [data-glyph=\"refresh\"] .nestg-steam-glyph-status {{ --nestg-steam-glyph-image:var(--nestg-steam-icon-refresh); }}\n.nestg-steam-control {{ position:relative; display:inline-flex; align-items:center; flex:0 0 auto; padding-left:12px; color:#f5f7fc; font-family:\"Segoe UI\",Arial,sans-serif; }}\n.nestg-steam-control::before {{ content:\"\"; position:absolute; left:0; top:50%; width:1px; height:28px; background:#354258; transform:translateY(-50%); }}\n.nestg-steam-header-card {{ position:relative; width:188px; height:44px; }}\n.nestg-steam-header-card::before {{ content:\"\"; position:absolute; inset:2px 0; border:1px solid #283746; border-radius:6px; background:linear-gradient(135deg,#101b25,#18232d); pointer-events:none; }}\n.nestg-steam-header-card:has(.nestg-steam-details:hover)::before {{ border-color:#4b7693; }}\n.nestg-steam-details, .nestg-steam-close {{ border:0; background:transparent; color:inherit; cursor:pointer; touch-action:manipulation; }}\n.nestg-steam-details {{ position:relative; display:flex; align-items:center; gap:12px; width:100%; min-width:44px; min-height:44px; padding:0 10px; border-radius:6px; }}\n.nestg-steam-symbol {{ width:28px; height:28px; }}\n.nestg-steam-label {{ font-size:14px; font-weight:800; white-space:nowrap; }}\n.nestg-steam-chevron {{ --nestg-steam-glyph-image:var(--nestg-steam-icon-chevron); width:12px; height:12px; margin-left:auto; color:#a7c5d9; }}\n.nestg-steam-details[aria-expanded=\"true\"] .nestg-steam-chevron {{ transform:rotate(180deg); }}\n.nestg-steam-switch {{ position:relative; width:48px; height:44px; padding:0; flex:0 0 auto; border:0; background:transparent; cursor:pointer; touch-action:manipulation; }}\n.nestg-steam-header-card > .nestg-steam-switch {{ position:absolute; right:32px; top:0; width:50px; }}\n.nestg-steam-switch::before {{ content:\"\"; position:absolute; inset:9px 0; border:1px solid #526277; border-radius:999px; background:linear-gradient(180deg,#303d4d,#253341); transition:background .16s,border-color .16s; }}\n.nestg-steam-thumb {{ position:absolute; top:13px; left:5px; width:18px; height:18px; border-radius:50%; background:#f2f7ff; box-shadow:0 1px 4px #0008; transition:transform .16s; }}\n.nestg-steam-switch[aria-checked=\"true\"]::before {{ background:linear-gradient(180deg,#66b5e2,#3988b1); border-color:#90def5; box-shadow:0 0 12px #49bee944,inset 0 0 3px #d4f4ff88; }}\n.nestg-steam-switch[aria-checked=\"true\"] .nestg-steam-thumb {{ transform:translateX(20px); }}\n.nestg-steam-switch:disabled {{ cursor:default; opacity:.65; }}\n.nestg-steam-control button:focus-visible, .nestg-steam-panel button:focus-visible {{ outline:2px solid #66c0f4; outline-offset:2px; }}\n.nestg-steam-panel[hidden], .nestg-steam-panel [hidden] {{ display:none!important; }}\n.nestg-steam-panel {{ position:fixed; z-index:20000; display:flex; flex-direction:column; box-sizing:border-box; width:460px; max-width:calc(100vw - 24px); max-height:calc(100vh - 72px); margin:0; padding:16px; border:1px solid #6596b1; border-radius:12px; background:radial-gradient(ellipse at 100% 0,#324c6029,transparent 65%),linear-gradient(135deg,#1d2a35,#18232d); box-shadow:0 16px 40px #0009,inset 0 1px 0 #b6d8eb0a; color:#f2f5f8; font-family:\"Segoe UI\",Arial,sans-serif; font-size:14px; line-height:1.5; }}\n.nestg-steam-panel *, .nestg-steam-panel *::before, .nestg-steam-panel *::after {{ box-sizing:border-box; }}\n.nestg-steam-panel::before {{ content:\"\"; position:absolute; top:-8px; left:var(--nestg-steam-arrow-left,64px); width:15px; height:15px; background:#1e2c38; border-top:1px solid #6596b1; border-left:1px solid #6596b1; transform:translateX(-50%) rotate(45deg); }}\n.nestg-steam-panel-heading {{ position:relative; display:flex; align-items:center; gap:12px; flex:0 0 auto; min-height:44px; padding-right:24px; margin-bottom:14px; }}\n.nestg-steam-panel-heading > div {{ flex:1; min-width:0; }}\n.nestg-steam-panel-icon {{ display:grid; place-items:center; width:36px; height:36px; flex:0 0 auto; border-radius:7px; background:linear-gradient(135deg,#314e83,#263c6c); box-shadow:inset 0 1px 0 #b6c9ff12; }}\n.nestg-steam-panel-icon .nestg-steam-glyph {{ width:26px; height:26px; }}\n.nestg-steam-panel h2 {{ margin:0 0 3px; font-size:18px; font-weight:700; line-height:1.3; color:#f5f7fc; }}\n.nestg-steam-panel-heading p {{ font-size:13px; line-height:1.4; }}\n.nestg-steam-panel p {{ margin:0; color:#a5c5dc; }}\n.nestg-steam-close {{ position:absolute; top:-8px; right:-8px; display:grid; place-items:center; width:44px; height:44px; padding:0; color:#a5c5dc; }}\n.nestg-steam-close .nestg-steam-glyph {{ --nestg-steam-glyph-image:var(--nestg-steam-icon-close); width:18px; height:18px; }}\n.nestg-steam-close:hover {{ color:#fff; }}\n.nestg-steam-panel-body {{ min-height:0; overflow-y:auto; overscroll-behavior:contain; scrollbar-width:thin; scrollbar-color:#42627b transparent; }}\n.nestg-steam-summary {{ display:flex; align-items:center; justify-content:space-between; flex-wrap:wrap; gap:8px 12px; min-height:28px; margin-bottom:8px; }}\n.nestg-steam-badge {{ display:inline-flex; align-items:center; gap:7px; max-width:100%; padding:3px 9px; border:1px solid #526d80; border-radius:6px; color:#b7cbda; font-size:12px; line-height:20px; }}\n.nestg-steam-badge strong {{ font-weight:600; overflow-wrap:anywhere; }}\n.nestg-steam-status-dot {{ width:7px; height:7px; flex:0 0 auto; border-radius:50%; background:currentColor; }}\n.nestg-steam-badge[data-tone=\"on\"] {{ border-color:#478c60; background:#2a624522; color:#96ecad; }}\n.nestg-steam-badge[data-tone=\"warning\"] {{ border-color:#a27d45; background:#9d752018; color:#f5cf91; }}\n.nestg-steam-badge[data-tone=\"busy\"] {{ border-color:#579bc1; color:#a3d9f6; }}\n.nestg-steam-badge[data-tone=\"busy\"] .nestg-steam-status-dot {{ width:10px; height:10px; background:none; border:2px solid currentColor; border-right-color:transparent; animation:nestg-steam-spin .7s linear infinite; }}\n.nestg-steam-benefits {{ display:grid; gap:4px; padding:0; margin:0 0 12px; list-style:none; }}\n.nestg-steam-benefits li {{ display:flex; align-items:center; gap:12px; min-height:28px; }}\n.nestg-steam-benefits li > span:last-child {{ min-width:0; overflow-wrap:anywhere; }}\n.nestg-steam-benefit-icon {{ display:grid; place-items:center; width:22px; height:22px; flex:0 0 auto; border:1px solid #7ac8f1; border-radius:50%; color:#7ac8f1; }}\n.nestg-steam-benefit-icon .nestg-steam-glyph {{ --nestg-steam-glyph-image:var(--nestg-steam-icon-check); width:14px; height:14px; }}\n.nestg-steam-panel .nestg-steam-notice {{ margin:0 0 12px; padding:8px 10px; border-left:2px solid #6b9ab7; border-radius:3px; background:#101e2833; color:#b8d6ed; font-size:13px; overflow-wrap:anywhere; }}\n.nestg-steam-notice[data-tone=\"warning\"] {{ border-left-color:#c9a168; color:#f5cf91; }}\n.nestg-steam-panel .nestg-steam-session {{ margin:0; padding:10px 0 0; border-top:1px solid #344d5e; color:#b8d6ed; font-size:13px; overflow-wrap:anywhere; }}\n.nestg-steam-panel .nestg-steam-feedback {{ padding:6px 0 0; color:#b8d6ed; font-size:13px; overflow-wrap:anywhere; }}\n.nestg-steam-actions {{ display:grid; grid-template-columns:1fr 1fr; gap:12px; flex:0 0 auto; margin-top:12px; }}\n.nestg-steam-actions button {{ display:flex; align-items:center; justify-content:center; gap:9px; min-height:42px; padding:8px 10px; border:1px solid #7bb9dc; border-radius:6px; color:#fff; font:600 14px \"Segoe UI\",Arial,sans-serif; cursor:pointer; touch-action:manipulation; }}\n.nestg-steam-primary {{ background:linear-gradient(180deg,#5da5dc 0,#337ab7 12px,#2c74b2 100%); box-shadow:0 0 14px #4c9ad82b,inset 0 1px 0 #bce5ff33; }}\n.nestg-steam-secondary {{ background:linear-gradient(135deg,#1a2a37,#15232e); }}\n.nestg-steam-actions button:hover:not(:disabled) {{ border-color:#b4e3ff; box-shadow:0 0 16px #4c9ad844; }}\n.nestg-steam-actions button:active:not(:disabled) {{ transform:translateY(1px); }}\n.nestg-steam-actions button:disabled {{ opacity:.6; cursor:default; }}\n.nestg-steam-primary .nestg-steam-glyph {{ --nestg-steam-glyph-image:var(--nestg-steam-icon-open); }}\n.nestg-steam-secondary .nestg-steam-glyph {{ --nestg-steam-glyph-image:var(--nestg-steam-icon-refresh); }}\n.nestg-steam-panel .nestg-steam-scope {{ display:flex; justify-content:center; flex:0 0 auto; margin-top:10px; color:#9fbcd1; font-size:12px; line-height:18px; text-align:center; }}\n.nestg-steam-scope > span {{ min-width:0; }}\n.nestg-steam-control[aria-busy=\"true\"] .nestg-steam-thumb::after {{ content:\"\"; position:absolute; inset:3px; border:2px solid #66c0f4; border-right-color:transparent; border-radius:50%; animation:nestg-steam-spin .7s linear infinite; }}\n@keyframes nestg-steam-spin {{ to {{ transform:rotate(360deg); }} }}\n@media (max-width:1080px) {{ .nestg-steam-label {{ display:none; }} .nestg-steam-control {{ padding-left:8px; }} .nestg-steam-header-card {{ width:126px; }} .nestg-steam-details {{ gap:8px; }} }}\n@media (max-width:680px) {{ .nestg-steam-control {{ padding-left:5px; }} .nestg-steam-header-card {{ width:118px; }} .nestg-steam-symbol {{ width:24px; height:24px; }} .nestg-steam-header-card > .nestg-steam-switch {{ width:44px; }} }}\n@media (max-width:520px) {{ .nestg-steam-header-card > .nestg-steam-switch, .nestg-steam-chevron {{ display:none; }} .nestg-steam-header-card {{ width:44px; }} .nestg-steam-details {{ justify-content:center; padding:0; }} .nestg-steam-panel-heading {{ gap:10px; }} .nestg-steam-benefits li {{ gap:10px; }} .nestg-steam-actions button {{ gap:8px; }} }}\n@media (max-width:360px) {{ .nestg-steam-panel {{ padding:12px; }} .nestg-steam-panel h2 {{ font-size:16px; }} .nestg-steam-panel-heading {{ gap:8px; }} .nestg-steam-actions button {{ gap:5px; font-size:13px; }} .nestg-steam-actions .nestg-steam-glyph {{ width:16px; height:16px; }} }}\n@media (prefers-reduced-motion:reduce) {{ .nestg-steam-thumb,.nestg-steam-switch::before {{ transition:none; }} .nestg-steam-control[aria-busy=\"true\"] .nestg-steam-thumb::after, .nestg-steam-badge[data-tone=\"busy\"] .nestg-steam-status-dot {{ animation:none; }} }}";

	internal static string Script => "(() => {\n    const documentId = globalThis.crypto?.randomUUID?.() ?? (Date.now().toString(36) + Math.random().toString(36));\n    let control, panel, lastState, timer, opener;\n    const setFeedback = text => {\n        const feedback = panel?.querySelector('[data-steam-connection-feedback]');\n        if (feedback) { feedback.textContent = text || ''; feedback.hidden = !text; }\n    };\n    const applyState = state => {\n        if (!control || !panel || state?.documentId !== documentId) return;\n        if (Number.isFinite(state.revision) && Number.isFinite(lastState?.revision) && state.revision < lastState.revision) return;\n        clearTimeout(timer);\n        lastState = state;\n        const busy = Boolean(state.busy) || state.kind === 'Checking';\n        control.setAttribute('aria-busy', String(busy));\n        panel.dataset.kind = state.kind || 'Unavailable';\n        const toggle = control.querySelector('[data-steam-connection-switch]');\n        toggle.setAttribute('aria-checked', String(Boolean(state.enabled)));\n        toggle.disabled = !state.canToggle || state.kind === 'Stopping';\n        toggle.title = state.detail || state.label || 'Chưa tích hợp bộ kết nối Steam';\n        const enabled = Boolean(state.enabled);\n        const cleanup = Boolean(state.cleanupPending);\n        const warning = cleanup || state.kind === 'Failed' || state.kind === 'Unknown' || (enabled && state.dnsEnabled !== true);\n        const badge = panel.querySelector('[data-steam-connection-badge]');\n        let label = enabled ? 'Đang bật' : 'Đang tắt';\n        let tone = enabled ? warning ? 'warning' : 'on' : 'muted';\n        if (state.kind === 'Starting') { label = 'Đang bật…'; tone = 'busy'; }\n        else if (state.kind === 'Stopping') { label = 'Đang tắt…'; tone = 'busy'; }\n        else if (busy) { label = 'Đang kiểm tra…'; tone = 'busy'; }\n        else if (state.kind === 'Unavailable') { label = 'Chưa sẵn sàng'; tone = 'warning'; }\n        else if (cleanup) { label = 'Chưa tắt xong'; tone = 'warning'; }\n        else if (enabled && state.dnsEnabled !== true) { label = 'Chưa xác nhận'; tone = 'warning'; }\n        else if (state.kind === 'Failed' && enabled) { label = 'Đang bật · có lỗi'; }\n        badge.dataset.tone = tone;\n        panel.querySelector('[data-steam-connection-status]').textContent = label;\n        // These describe possible benefits, never individual probe results.\n        panel.querySelector('[data-steam-connection-benefits]').hidden = !enabled || cleanup;\n        panel.querySelector('[data-steam-connection-refresh-label]').textContent = cleanup ? 'Thử tắt lại' : 'Kiểm tra lại';\n        let description = '';\n        if (state.kind === 'Starting') description = 'Đang chuẩn bị hỗ trợ. Windows có thể yêu cầu quyền quản trị.';\n        else if (state.kind === 'Stopping') description = 'Đang dừng hỗ trợ và khôi phục cấu hình kết nối.';\n        else if (busy) description = 'Đang kiểm tra kết nối Steam…';\n        else if (state.kind === 'Off') description = 'Bật công tắc Steam phía trên để sử dụng hỗ trợ.';\n        else if (warning || state.kind === 'Unavailable') description = state.detail || state.label || 'Chưa xác nhận được kết nối. Bạn có thể kiểm tra lại.';\n        else if (!enabled) description = 'Steam đang truy cập được; hỗ trợ hiện đang tắt.';\n        else if (!state.independentVerified) description = state.detail || 'Chưa xác nhận kết nối Steam độc lập. Bạn có thể kiểm tra lại.';\n        const failed = [['login', 'Đăng nhập'], ['store', 'Cửa hàng'], ['images', 'Ảnh']]\n            .filter(([key]) => state.checks?.[key] === 'failed').map(([, name]) => name);\n        if (!busy && failed.length) description += (description ? ' ' : '') + 'Chưa kết nối: ' + failed.join(', ') + '.';\n        const notice = panel.querySelector('[data-steam-connection-description]');\n        notice.textContent = description;\n        notice.hidden = !description;\n        notice.dataset.tone = warning ? 'warning' : 'muted';\n        panel.querySelector('[data-steam-connection-open]').disabled = busy;\n        panel.querySelector('[data-steam-connection-refresh]').disabled = busy;\n        setFeedback(state.feedback);\n        position();\n    };\n    const position = () => {\n        if (!panel || panel.hidden) return;\n        const anchor = control.getBoundingClientRect();\n        const viewport = window.visualViewport;\n        const width = Math.min(window.innerWidth, viewport?.width ?? window.innerWidth);\n        const height = Math.min(window.innerHeight, viewport?.height ?? window.innerHeight);\n        const top = Math.min(Math.max(12, anchor.bottom + 12), Math.max(12, height - 150));\n        panel.style.maxWidth = Math.max(0, width - 24) + 'px';\n        panel.style.maxHeight = Math.max(0, height - top - 12) + 'px';\n        panel.style.top = top + 'px';\n        const panelWidth = panel.getBoundingClientRect().width;\n        const left = Math.max(12, Math.min(anchor.left, width - panelWidth - 12));\n        panel.style.left = left + 'px';\n        panel.style.setProperty('--nestg-steam-arrow-left', Math.max(24, Math.min(panelWidth - 24, anchor.left + anchor.width / 2 - left)) + 'px');\n    };\n    const close = restoreFocus => {\n        if (!panel || panel.hidden) return;\n        panel.hidden = true;\n        for (const button of control.querySelectorAll('[data-steam-connection-details]')) button.setAttribute('aria-expanded', 'false');\n        if (restoreFocus && opener?.isConnected) opener.focus();\n    };\n    const post = (type, enabled) => {\n        if (!window.chrome?.webview?.postMessage) { setFeedback('Chức năng này chỉ hoạt động trong NestG Launcher.'); return; }\n        window.chrome.webview.postMessage({type, documentId, ...(typeof enabled === 'boolean' ? {enabled} : {})});\n    };\n    const request = (type, enabled) => {\n        if (control.getAttribute('aria-busy') === 'true' && !(type === 'setSteamConnectionEnabled' && enabled === false)) return;\n        control.setAttribute('aria-busy', 'true');\n        for (const button of panel.querySelectorAll('.nestg-steam-actions button')) button.disabled = true;\n        if (type === 'refreshSteamConnection') setFeedback('Đang đọc trạng thái hỗ trợ Steam…');\n        clearTimeout(timer);\n        timer = setTimeout(() => {\n            applyState(lastState || {documentId, kind:'Unavailable', canToggle:false});\n            setFeedback('Chưa nhận được phản hồi. Vui lòng thử lại.');\n        }, 8000);\n        post(type, enabled);\n    };\n    const bind = () => {\n        control = document.querySelector('[data-steam-connection-control]');\n        panel = control?.querySelector('[data-steam-connection-panel]');\n        if (!control || !panel) return;\n        // Portal avoids header clipping, stacking contexts and native window dragging.\n        document.body.append(panel);\n        control.addEventListener('mousedown', event => event.stopPropagation());\n        panel.addEventListener('mousedown', event => event.stopPropagation());\n        for (const button of control.querySelectorAll('[data-steam-connection-details]')) button.addEventListener('click', () => {\n            if (!panel.hidden) { close(true); return; }\n            opener = button;\n            panel.hidden = false;\n            for (const item of control.querySelectorAll('[data-steam-connection-details]')) item.setAttribute('aria-expanded', 'true');\n            position();\n            panel.querySelector('[data-steam-connection-close]').focus();\n        });\n        panel.querySelector('[data-steam-connection-close]').addEventListener('click', () => close(true));\n        document.addEventListener('pointerdown', event => {\n            if (!panel.hidden && !control.contains(event.target) && !panel.contains(event.target)) close(false);\n        });\n        document.addEventListener('keydown', event => {\n            if (!panel.hidden && event.key === 'Escape') { event.preventDefault(); event.stopPropagation(); close(true); }\n        }, true);\n        window.addEventListener('resize', position);\n        window.addEventListener('scroll', position, true);\n        window.visualViewport?.addEventListener('resize', position);\n        control.querySelector('[data-steam-connection-switch]').addEventListener('click', event => {\n            if (!event.currentTarget.disabled) request('setSteamConnectionEnabled', control.getAttribute('aria-busy') === 'true' ? false : event.currentTarget.getAttribute('aria-checked') !== 'true');\n        });\n        panel.querySelector('[data-steam-connection-open]').addEventListener('click', event => {\n            if (!event.currentTarget.disabled) request('openSteamConnectionClient');\n        });\n        panel.querySelector('[data-steam-connection-refresh]').addEventListener('click', event => {\n            if (!event.currentTarget.disabled) {\n                if (lastState?.cleanupPending) request('setSteamConnectionEnabled', false);\n                else request('refreshSteamConnection');\n            }\n        });\n        post('steamConnectionReady');\n    };\n    window.__nestgSteamConnection = { documentId, setState:applyState, close:() => close(true) };\n    if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', bind, {once:true});\n    else bind();\n})();";

	internal static string Render()
	{
		return "<div class=\"nestg-steam-control\" data-steam-connection-control>\n    <div class=\"nestg-steam-header-card\">\n        <button type=\"button\" class=\"nestg-steam-details\" data-steam-connection-details\n            aria-label=\"Hỗ trợ kết nối Steam\" aria-haspopup=\"dialog\" aria-expanded=\"false\" aria-controls=\"nestg-steam-panel\">\n            <span class=\"nestg-steam-symbol nestg-steam-glyph nestg-steam-glyph-steam\" aria-hidden=\"true\"></span>\n            <span class=\"nestg-steam-label\">Steam</span>\n            <span class=\"nestg-steam-chevron nestg-steam-glyph\" aria-hidden=\"true\"></span>\n        </button>\n        <button type=\"button\" class=\"nestg-steam-switch\" data-steam-connection-switch role=\"switch\"\n            aria-label=\"Bật hoặc tắt hỗ trợ kết nối Steam\" aria-checked=\"false\" title=\"Đang đọc trạng thái hỗ trợ Steam\" disabled>\n            <span class=\"nestg-steam-thumb\"></span>\n        </button>\n    </div>\n    <section class=\"nestg-steam-panel\" id=\"nestg-steam-panel\" data-steam-connection-panel\n        role=\"dialog\" aria-modal=\"false\" aria-labelledby=\"nestg-steam-title\" hidden>\n        <div class=\"nestg-steam-panel-heading\">\n            <span class=\"nestg-steam-panel-icon\" aria-hidden=\"true\"><span class=\"nestg-steam-glyph nestg-steam-glyph-steam\"></span></span>\n            <div><h2 id=\"nestg-steam-title\">Hỗ trợ kết nối Steam</h2><p>Truy cập Steam khi kết nối bị chặn.</p></div>\n            <button type=\"button\" class=\"nestg-steam-close\" data-steam-connection-close aria-label=\"Đóng chi tiết kết nối Steam\"><span class=\"nestg-steam-glyph\" aria-hidden=\"true\"></span></button>\n        </div>\n        <div class=\"nestg-steam-panel-body\">\n            <div class=\"nestg-steam-summary\" data-steam-connection-summary>\n                <span>Khi bật hỗ trợ:</span>\n                <span class=\"nestg-steam-badge\" data-steam-connection-badge data-tone=\"muted\" role=\"status\" aria-live=\"polite\" aria-atomic=\"true\">\n                    <span class=\"nestg-steam-status-dot\" aria-hidden=\"true\"></span><strong data-steam-connection-status>Đang đọc trạng thái</strong>\n                </span>\n            </div>\n            <ul class=\"nestg-steam-benefits\" data-steam-connection-benefits aria-label=\"Các công dụng hỗ trợ Steam\" hidden>\n                <li><span class=\"nestg-steam-benefit-icon\" aria-hidden=\"true\"><span class=\"nestg-steam-glyph\"></span></span><span>Hỗ trợ mở trang tạo tài khoản Steam</span></li>\n                <li><span class=\"nestg-steam-benefit-icon\" aria-hidden=\"true\"><span class=\"nestg-steam-glyph\"></span></span><span>Hỗ trợ khắc phục lỗi kết nối Steam</span></li>\n                <li><span class=\"nestg-steam-benefit-icon\" aria-hidden=\"true\"><span class=\"nestg-steam-glyph\"></span></span><span>Hỗ trợ đăng nhập và mở cửa hàng</span></li>\n                <li><span class=\"nestg-steam-benefit-icon\" aria-hidden=\"true\"><span class=\"nestg-steam-glyph\"></span></span><span>Hỗ trợ tải ảnh Steam</span></li>\n            </ul>\n            <p class=\"nestg-steam-notice\" data-steam-connection-description role=\"status\" aria-live=\"polite\" aria-atomic=\"true\" hidden></p>\n            <p class=\"nestg-steam-session\" data-steam-connection-session>Mỗi lần mở launcher, bạn cần bật hỗ trợ Steam.</p>\n            <p class=\"nestg-steam-feedback\" data-steam-connection-feedback role=\"status\" aria-live=\"polite\" hidden></p>\n        </div>\n        <div class=\"nestg-steam-actions\">\n            <button type=\"button\" class=\"nestg-steam-primary\" data-steam-connection-open><span class=\"nestg-steam-glyph\" aria-hidden=\"true\"></span>Mở Steam</button>\n            <button type=\"button\" class=\"nestg-steam-secondary\" data-steam-connection-refresh><span class=\"nestg-steam-glyph\" aria-hidden=\"true\"></span><span data-steam-connection-refresh-label>Kiểm tra lại</span></button>\n        </div>\n        <p class=\"nestg-steam-scope\"><span>Chỉ áp dụng cho Steam trên máy này.</span></p>\n    </section>\n</div>";
	}
